      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Arial, sans-serif;
      background:
        radial-gradient(circle at top, #172554 0, var(--bg) 45%),
        linear-gradient(180deg, #0f172a 0%, var(--bg) 100%);
      color: var(--text);
    }

    .skip-link {
      position: absolute;
      left: 1rem;
      top: 1rem;
      transform: translateY(-200%);
      background: var(--text);
      color: #000;
      padding: 0.75rem 1rem;
      border-radius: 0.5rem;
      font-weight: 700;
      text-decoration: none;
    }

    .skip-link:focus {
      transform: translateY(0);
      outline: 3px solid var(--accent);
      outline-offset: 2px;
    }

    main {
      display: grid;
      place-items: center;
      min-height: 100vh;
      padding: 2rem 1rem;
    }

    .card {
      width: min(100%, 38rem);
      background: linear-gradient(180deg, #111827 0%, #0f172a 100%);
      border: 1px solid var(--panel-border);
      border-radius: 1.25rem;
      box-shadow: var(--shadow);
      padding: 2rem;
    }

    h1 {
      margin: 0 0 0.75rem;
      font-size: clamp(1.9rem, 4vw, 2.5rem);
      line-height: 1.1;
    }

    .intro {
      margin: 0 0 1.75rem;
      color: var(--muted);
      line-height: 1.6;
    }

    form {
      display: grid;
      gap: 1.25rem;
    }

    .form-field {
      display: grid;
      gap: 0.45rem;
    }

    label {
      font-weight: 700;
    }

    .required-indicator {
      color: #fbbf24;
    }

    input {
      width: 100%;
      min-width: 0;
      border: 1px solid var(--panel-highlight);
      border-radius: 0.8rem;
      background: #0b1220;
      color: var(--text);
      padding: 0.95rem 1rem;
      font: inherit;
      transition: border-color 0.2s ease, box-shadow 0.2s ease, background-color 0.2s ease;
    }

    input::placeholder {
      color: #94a3b8;
    }

    input:focus {
      outline: 2px solid transparent;
      border-color: var(--accent);
      box-shadow: 0 0 0 3px #1d4ed8;
    }

    input[aria-invalid="true"] {
      border-color: var(--error-strong);
      box-shadow: 0 0 0 3px #7f1d1d;
    }

    .helper-text,
    .field-error,
    .status-message {
      margin: 0;
      font-size: 0.95rem;
      line-height: 1.5;
      overflow-wrap: anywhere;
    }

    .helper-text {
      color: var(--muted);
    }

    .field-error {
      color: var(--error);
      min-height: 1.5em;
    }

    .status-message {
      border-radius: 0.85rem;
      padding: 0.9rem 1rem;
      border: 1px solid transparent;
      min-height: 3.25rem;
    }

    .status-message:empty {
      display: none;
    }

    .status-message[data-state="success"] {
      background: var(--success-bg);
      border-color: var(--success-border);
      color: #dcfce7;
    }

    .status-message[data-state="error"] {
      background: #3a1212;
      border-color: var(--error-strong);
      color: #fee2e2;
    }

    button {
      border: 0;
      border-radius: 999px;
      padding: 0.95rem 1.4rem;
      font: inherit;
      font-weight: 700;
      color: #081120;
      background: linear-gradient(180deg, #93c5fd 0%, var(--accent) 100%);
      cursor: pointer;
      transition: transform 0.15s ease, background 0.2s ease;
    }

    button:hover {
      background: linear-gradient(180deg, #bfdbfe 0%, var(--accent-strong) 100%);
      transform: translateY(-1px);
    }

    button:focus-visible {
      outline: 3px solid #dbeafe;
      outline-offset: 3px;
