<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>
  <main id="main-content">
    <section class="card" aria-labelledby="support-heading">
      <h1 id="support-heading">Contact support</h1>
      <p class="intro">Send us your details and our support team will follow up as soon as possible.</p>

      <form id="support-form" novalidate>
        <div class="form-field">
          <label for="full-name">Full name <span class="required-indicator" aria-hidden="true">*</span></label>
          <input
            id="full-name"
            name="fullName"
            type="text"
            autocomplete="name"
            required
            aria-required="true"
            aria-describedby="full-name-error"
          >
          <p class="field-error" id="full-name-error" aria-live="polite"></p>
        </div>

        <div class="form-field">
          <label for="email-address">Email address <span class="required-indicator" aria-hidden="true">*</span></label>
          <input
            id="email-address"
            name="email"
            type="email"
            autocomplete="email"
            inputmode="email"
            required
            aria-required="true"
            aria-describedby="email-address-error"
          >
          <p class="field-error" id="email-address-error" aria-live="polite"></p>
        </div>

        <div class="form-field">
          <label for="phone-number">Phone number</label>
          <input
            id="phone-number"
            name="phone"
            type="tel"
            autocomplete="tel"
            inputmode="tel"
            aria-describedby="phone-helper phone-number-error"
          >
          <p class="helper-text" id="phone-helper">Expected format: optional leading + followed by 10 to 15 digits, for example +14155550123.</p>
          <p class="field-error" id="phone-number-error" aria-live="polite"></p>
        </div>

        <p class="status-message" id="form-status" aria-live="polite"></p>

        <button type="submit">Submit request</button>
      </form>
    </section>
  </main>

  <script>
    const form = document.getElementById('support-form');
    const statusMessage = document.getElementById('form-status');

    const fields = {
      fullName: {
        input: document.getElementById('full-name'),
        error: document.getElementById('full-name-error'),
        validate(value) {
          const trimmedValue = value.trim();

          if (!trimmedValue) {
            return 'Enter your full name.';
          }

          if (trimmedValue.length < 2 || !/[A-Za-z]/.test(trimmedValue)) {
            return 'Enter a valid full name.';
          }

          return '';
        }
      },
      email: {
        input: document.getElementById('email-address'),
        error: document.getElementById('email-address-error'),
        validate(value) {
          const trimmedValue = value.trim();
          const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

          if (!trimmedValue) {
            return 'Enter your email address.';
          }

          if (!emailPattern.test(trimmedValue)) {
            return 'Enter a valid email address.';
          }

          return '';
        }
      },
      phone: {
        input: document.getElementById('phone-number'),
        error: document.getElementById('phone-number-error'),
        validate(value) {
          const trimmedValue = value.trim();
          const phonePattern = /^\+?\d{10,15}$/;

          if (!trimmedValue) {
            return '';
          }

          if (!phonePattern.test(trimmedValue)) {
            return 'Use 10 to 15 digits with an optional leading +.';
          }

          return '';
        }
      }
    };

    function setFieldState(field, message) {
      field.error.textContent = message;
      field.input.setAttribute('aria-invalid', message ? 'true' : 'false');
    }

    function validateField(field) {
      const message = field.validate(field.input.value);
      setFieldState(field, message);
      return message;
    }

    function clearStatus() {
      statusMessage.textContent = '';
      statusMessage.dataset.state = '';
    }

    Object.values(fields).forEach((field) => {
      field.input.addEventListener('input', () => {
        validateField(field);
        clearStatus();
      });

      field.input.addEventListener('blur', () => {
        validateField(field);
      });
    });

    form.addEventListener('submit', (event) => {
      event.preventDefault();

      const fieldEntries = Object.values(fields);
      const invalidFields = fieldEntries.filter((field) => validateField(field));

      if (invalidFields.length > 0) {
        invalidFields[0].input.focus();
        statusMessage.dataset.state = 'error';
        statusMessage.textContent = 'Fix the highlighted fields and submit the form again.';
        return;
      }

      statusMessage.dataset.state = 'success';
      statusMessage.textContent = 'Your support request is ready to send.';
      form.reset();
      fieldEntries.forEach((field) => setFieldState(field, ''));
    });
  </script>
</body>
</html>
